(1612498, 215791, 40355, '<td valign="top">This is really neat!  The distortion adds to the primitive feel.  8</td>', 'This is really neat!  The distortion adds to the primitive feel.  8', '2005-08-15 15:19:10.000000', NULL, 1),
(1612508, 216102, 35739, '<td valign="top">Would like to have seen the dash more in focus.</td>', 'Would like to have seen the dash more in focus.', '2005-08-15 15:23:11.000000', NULL, 1),
(1612533, 215485, 33515, '<td valign="top">Regardless if the title carries the year or not I am have a problem fitting this into a period of time.</td>', 'Regardless if the title carries the year or not I am have a problem fitting this into a period of time.', '2005-08-15 15:31:40.000000', NULL, 1),
(1612602, 216098, 40355, '<td valign="top">Good old time look to the picture, well done!</td>', 'Good old time look to the picture, well done!', '2005-08-15 15:57:36.000000', NULL, 1),
(1612603, 214916, 40355, '<td valign="top">Are you sure that this was 1950?  I looks older than that.  Whatever the year, this is a great picture, well rooted in a specific era.  8</td>', 'Are you sure that this was 1950?  I looks older than that.  Whatever the year, this is a great picture, well rooted in a specific era.  8', '2005-08-15 15:58:41.000000', NULL, 1),
(1612606, 215245, 40355, '<td valign="top">Beautiful, simply beautiful.  Great colors, composition, and shot in general.  A border might have looked nice, but other wise no complaints :)  8</td>', 'Beautiful, simply beautiful.  Great colors, composition, and shot in general.  A border might have looked nice, but other wise no complaints :)  8', '2005-08-15 15:59:30.000000', NULL, 1),
(1612607, 213371, 40355, '<td valign="top">Has the feel of an old-time newspaper photo.  Very well done, well grounded in its time. 8</td>', 'Has the feel of an old-time newspaper photo.  Very well done, well grounded in its time. 8', '2005-08-15 15:59:59.000000', NULL, 1),
(1612610, 214536, 40355, '<td valign="top">Hmmm...doesn''t exactly yell a year at me, or even a specific decade.  And there''s not date in the title....</td>', 'Hmmm...doesn''t exactly yell a year at me, or even a specific decade.  And there''s not date in the title....', '2005-08-15 16:01:21.000000', NULL, 1),
